package org.eclipse.jdt.internal.ui.refactoring.contentassist;
import org.eclipse.jdt.core.ICompilationUnit;
interface ICompletionContextRequestor {
    ICompilationUnit getOriginalCu();
}
public class CUPositionCompletionProcessor {
    private ICompletionContextRequestor fCompletionContextRequestor;
    public Object[] computeCompletionProposals() {
        if (fCompletionContextRequestor.getOriginalCu() == null) {
            return null;
        }
        return new Object[0];
    }
}

